cd /tmp/claude-0/-home-user/b7d31bcb-5d4a-54b3-81be-c137021a331c/scratchpad/ds-runs/3a55120663/analysis; python3 -I -c "
import sqlite3,math;c=sqlite3.connect('warehouse.db')
d={}
for w,p,k,s,cl in c.execute('''select case when date>='2026-09-28' then 2 else 1 end,platform,country,sum(searches),sum(clicks) from search_daily group by 1,2,3'''):d[w,p,k]=(s,cl)
segs=[(p,k) for p in('desktop','mobile') for k in('US','other')]
T1=sum(d[1,*x][0] for x in segs);T2=sum(d[2,*x][0] for x in segs)
rate=0;var=0;mix=0
for x in segs:
    s1,c1=d[1,*x];s2,c2=d[2,*x];r1=c1/s1;r2=c2/s2
    w2=s2/T2;w1=s1/T1
    rate+=w2*(r2-r1); mix+=(w2-w1)*r1
    var+=w2**2*(r1*(1-r1)/s1+r2*(1-r2)/s2)
print('total',sum(d[2,*x][1] for x in segs)/T2-sum(d[1,*x][1] for x in segs)/T1)
print('rate(within, W2 weights)',rate*100,'+-',1.96*math.sqrt(var)*100,'mix',mix*100)
"

